// On-demand importer for newer public HF days. Runs off the rendering thread.
import {haversine} from './transport-math.js';
export function decodeCoordinates(lon,lat){lon=Number(lon);lat=Number(lat);return Math.abs(lon)<=180&&Math.abs(lat)<=90?[lon,lat]:[Math.trunc(lon+3962591)/1800000,Math.trunc(lat+3193782)/1200000];}
export function parseMoscowTime(value){const m=/^(\d{2})\.(\d{2})\.(\d{4}) (\d{2}):(\d{2}):(\d{2})$/.exec(value);if(!m)return NaN;return Date.UTC(+m[3],+m[2]-1,+m[1],+m[4]-3,+m[5],+m[6])/1000;}
export function* tsvRows(text){let field='',row=[],quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c==='\t'&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))yield row;row=[];field='';}else field+=c;}if(field||row.length){row.push(field);yield row;}}
function heading(a,b){const r=Math.PI/180,p=a[2]*r,q=b[2]*r,d=(b[1]-a[1])*r;return Math.round((Math.atan2(Math.sin(d)*Math.cos(q),Math.cos(p)*Math.sin(q)-Math.sin(p)*Math.cos(q)*Math.cos(d))/r+360)%360);}
export function importGPS(text,date,bounds,stops=[]){
 const epoch=Date.parse(date+'T00:00:00+03:00')/1000,rows=tsvRows(text),header=rows.next().value;if(!header?.includes('lasttime'))throw Error('Неизвестный формат GPS');const fields=Object.fromEntries(header.map((v,i)=>[v,i]));const quality={rawRows:0,outsideMap:0,duplicates:0,invalidRows:0,validSegments:0,rejectedSegments:0},dedup=new Map(),offsets=new Map();
 for(const row of rows){quality.rawRows++;const r=k=>row[fields[k]],t=parseMoscowTime(r('lasttime')),[lon,lat]=decodeCoordinates(r('lon'),r('lat')),collected=Number(r('created_at'));if(!Number.isFinite(t)||!Number.isFinite(lon)||!Number.isFinite(lat)||!r('id_api')||!r('rid')){quality.invalidRows++;continue;}if(lon<bounds[0]||lon>bounds[2]||lat<bounds[1]||lat>bounds[3]){quality.outsideMap++;continue;}const key=r('id_api')+':'+r('rid')+':'+t;if(dedup.has(key))quality.duplicates++;const offset=Math.round((collected-t)/3600);offsets.set(offset,(offsets.get(offset)||0)+1);if(!dedup.has(key)||collected>=dedup.get(key).collected)dedup.set(key,{id:r('id_api'),route:r('rid'),number:r('rnum'),type:r('rtype'),lowFloor:r('low_floor')==='1',t,lon,lat,jump:r('big_jump')==='1',collected});}
 const grouped=new Map();for(const row of dedup.values()){const key=row.id+':'+row.route;if(!grouped.has(key))grouped.set(key,{id:row.id,route:row.type+':'+row.number,sourceRoute:row.route,number:row.number,type:row.type,lowFloor:row.lowFloor,rows:[]});grouped.get(key).rows.push([row.t,row.lon,row.lat,row.jump]);}dedup.clear();
 const mx=111320*Math.cos((bounds[1]+bounds[3])*Math.PI/360),cell=(lon,lat)=>[Math.floor((lon-bounds[0])*mx/100),Math.floor((lat-bounds[1])*111320/100)],stopCells=new Map();stops.forEach((s,i)=>{if(!s.inMap||s.type!=='0')return;const key=cell(s.lon,s.lat).join(':');if(!stopCells.has(key))stopCells.set(key,[]);stopCells.get(key).push(i);});
 const nearest=(lon,lat)=>{const [x,y]=cell(lon,lat);let best=null,min=70;for(let xx=x-1;xx<=x+1;xx++)for(let yy=y-1;yy<=y+1;yy++)for(const i of stopCells.get(xx+':'+yy)||[]){const s=stops[i],d=haversine(lon,lat,s.lon,s.lat);if(d<min){min=d;best=i;}}return best;};
 let start=Infinity,end=-Infinity;const tracks=[];for(const tr of grouped.values()){tr.rows.sort((a,b)=>a[0]-b[0]);const points=[],visits=[];let prev=null,direction=0,lastStop=null;for(const row of tr.rows){const [t,lon,lat,jump]=row;start=Math.min(start,t);end=Math.max(end,t);let speed=null,valid=false;if(prev){const dt=t-prev[0],meters=haversine(prev[1],prev[2],lon,lat),v=meters/dt*3.6;valid=dt>=15&&dt<=180&&v<=120&&!jump&&!prev[3];if(valid){speed=Math.round(v*10)/10;quality.validSegments++;if(meters>5)direction=heading(prev,row);}else quality.rejectedSegments++;}const stop=nearest(lon,lat);if(stop!==null&&valid&&stop!==lastStop){const s=stops[stop];if(haversine(prev[1],prev[2],s.lon,s.lat)>70)visits.push([t-epoch,stop,Math.floor(((direction+45)%360)/90)]);}if(stop!==null)lastStop=stop;else if(lastStop!==null){const s=stops[lastStop];if(haversine(lon,lat,s.lon,s.lat)>110)lastStop=null;}points.push([t-epoch,Math.round(lon*1e6),Math.round(lat*1e6),speed,direction]);prev=row;}delete tr.rows;tracks.push({...tr,points,visits});}
 if(!tracks.length)throw Error('Нет GPS-точек в пределах карты');quality.points=tracks.reduce((n,t)=>n+t.points.length,0);quality.vehicles=new Set(tracks.map(t=>t.id)).size;quality.routes=new Set(tracks.map(t=>t.route)).size;quality.collectionOffsetHours=[...offsets].sort((a,b)=>b[1]-a[1])[0]?.[0]??0;
 return {version:1,date,epoch,start:start-epoch,end:end-epoch,bounds,quality,source:'https://huggingface.co/datasets/daniilakk/cheboksary-public-transport-gps-daily/blob/main/transport/'+date+'.csv',tracks};
}
if(typeof self!=='undefined'&&typeof document==='undefined')self.onmessage=async({data})=>{try{const {date,bounds,stops}=data;self.postMessage({progress:'Загрузка нового GPS '+date+'…'});const url='https://huggingface.co/datasets/daniilakk/cheboksary-public-transport-gps-daily/resolve/main/transport/'+date+'.csv',response=await fetch(url);if(!response.ok)throw Error('GPS: HTTP '+response.status);const text=await response.text();self.postMessage({progress:'Нормализация координат и времени GPS…'});self.postMessage({day:importGPS(text,date,bounds,stops)});}catch(error){self.postMessage({error:error.message});}};
